# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DENETLEYİCİ VE DÜZENLEYİCİ SİSTEMLERİN SAĞLIĞI (FB.6.3.9)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sağlığı Koruma İlkeleri (Yapılması Gerekenler)</text>\n  <text x="40" y="98" font-size="12" fill="#14532d">• Yeterli, dengeli beslenme ve B vitamini alımı</text>\n  <text x="40" y="122" font-size="12" fill="#14532d">• Tiroit sağlığı için iyotlu tuz kullanımı</text>\n  <text x="40" y="146" font-size="12" fill="#14532d">• Düzenli uyku (büyüme hormonu salgısı için)</text>\n  <text x="40" y="170" font-size="12" fill="#14532d">• Bisiklet/paten sürerken kask ve dizlik takma</text>\n  <text x="40" y="194" font-size="12" fill="#14532d">• Düzenli egzersiz, spor ve stresten uzak yaşam</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Sağlıklı Sinir Sistemi ve İç Salgı Bezleri</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Kaçınılması Gereken Zararlı Etkenler</text>\n  <text x="380" y="98" font-size="12" fill="#7f1d1d">• Sigara, alkol ve bağımlılık yapıcı maddeler</text>\n  <text x="380" y="122" font-size="12" fill="#7f1d1d">• Doktor kontrolü dışında bilinçsiz ilaç/hormon</text>\n  <text x="380" y="146" font-size="12" fill="#7f1d1d">• Kafa ve omurga darbeleri (felç riski)</text>\n  <text x="380" y="170" font-size="12" fill="#7f1d1d">• Aşırı şekerli ve hazır gıda tüketimi (diyabet)</text>\n  <text x="380" y="194" font-size="12" fill="#7f1d1d">• Uzun süreli ekran bağımlılığı ve uykusuzluk</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">Hastalıklar: Diyabet, Guatr, Devlik/Cücelik, Felç</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">4. ÜNİTE: IŞIĞIN DOĞRUSAL YAYILMASI VE YANSIMA İLKELERİ</text>\n  <rect x="20" y="48" width="660" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <circle cx="110" cy="140" r="24" fill="#facc15" stroke="#eab308" stroke-width="2"/>\n  <text x="110" y="185" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">Işık Kaynağı</text>\n  <line x1="140" y1="140" x2="290" y2="140" stroke="#ea580c" stroke-width="3"/>\n  <polygon points="290,140 278,134 278,146" fill="#ea580c"/>\n  <line x1="138" y1="125" x2="285" y2="95" stroke="#ea580c" stroke-width="2.5"/>\n  <polygon points="285,95 272,92 275,103" fill="#ea580c"/>\n  <line x1="138" y1="155" x2="285" y2="185" stroke="#ea580c" stroke-width="2.5"/>\n  <polygon points="285,185 275,177 272,188" fill="#ea580c"/>\n  <text x="215" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Işık Işını Modeli (Doğrusal Yayılma)</text>\n  <rect x="335" y="65" width="325" height="155" rx="8" fill="#ffffff" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="497" y="90" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">Işığın Yayılması ve Yansıması</text>\n  <text x="350" y="116" font-size="12" fill="#1e293b">• Kaynaktan çıkan ışık her yönde doğrusal yayılır.</text>\n  <text x="350" y="140" font-size="12" fill="#1e293b">• Işığın izlediği yolu gösteren oklu doğruya ışın denir.</text>\n  <text x="350" y="164" font-size="12" fill="#1e293b">• Işığın bir yüzeye çarpıp geri dönmesine yansıma denir.</text>\n  <text x="350" y="188" font-size="12" fill="#1e293b">• Görme olayı için cisimden gözümüze ışık yansımalıdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DÜZGÜN YANSIMA VE DAĞINIK YANSIMA KARŞILAŞTIRMASI (FB.6.4.1)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Düzgün Yansıma (Parlak ve Pürüzsüz)</text>\n  <line x1="60" y1="165" x2="300" y2="165" stroke="#0284c7" stroke-width="4"/>\n  <line x1="80" y1="95" x2="140" y2="165" stroke="#ef4444" stroke-width="2.2"/>\n  <line x1="120" y1="95" x2="180" y2="165" stroke="#ef4444" stroke-width="2.2"/>\n  <line x1="160" y1="95" x2="220" y2="165" stroke="#ef4444" stroke-width="2.2"/>\n  <line x1="140" y1="165" x2="200" y2="95" stroke="#16a34a" stroke-width="2.2"/>\n  <line x1="180" y1="165" x2="240" y2="95" stroke="#16a34a" stroke-width="2.2"/>\n  <line x1="220" y1="165" x2="280" y2="95" stroke="#16a34a" stroke-width="2.2"/>\n  <text x="180" y="192" text-anchor="middle" font-size="11.5" fill="#155e75">Paralel gelen ışınlar birbirine paralel yansır.</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0e7490">Örnek: Ayna, durgun su, buruşmamış folyo</text>\n  <text x="180" y="230" text-anchor="middle" font-size="11" fill="#0891b2">Net ve parlak görüntü oluşur.</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">2. Dağınık Yansıma (Mat ve Pürüzlü)</text>\n  <polyline points="400,165 425,155 450,170 475,154 500,168 525,156 550,170 575,155 600,168 640,160" fill="none" stroke="#ea580c" stroke-width="3.5"/>\n  <line x1="420" y1="95" x2="475" y2="154" stroke="#ef4444" stroke-width="2.2"/>\n  <line x1="460" y1="95" x2="515" y2="161" stroke="#ef4444" stroke-width="2.2"/>\n  <line x1="500" y1="95" x2="555" y2="167" stroke="#ef4444" stroke-width="2.2"/>\n  <line x1="475" y1="154" x2="585" y2="105" stroke="#16a34a" stroke-width="2.2"/>\n  <line x1="515" y1="161" x2="505" y2="90" stroke="#16a34a" stroke-width="2.2"/>\n  <line x1="555" y1="167" x2="635" y2="120" stroke="#16a34a" stroke-width="2.2"/>\n  <text x="520" y="192" text-anchor="middle" font-size="11.5" fill="#9a3412">Paralel gelen ışınlar farklı yönlere dağınık yansır.</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#c2410c">Örnek: Dalgalı su, buruşuk folyo, kağıt, duvar</text>\n  <text x="520" y="230" text-anchor="middle" font-size="11" fill="#ea580c">Net görüntü oluşmaz, gözü yormadan aydınlatır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
